import UIKit

/// The AorusGram mark for exported material.
///
/// The conversation-share PDF used to draw the generic in-app AI glyph, tinted to the accent —
/// a plain shape that read as a square beside the "AorusAI" wordmark. This is the real brand
/// logo instead, embedded so it needs no bundle resource: the white mark for a dark page, the
/// inked mark for a light one, each trimmed to its own content so it fills the space it is
/// given rather than floating in transparent padding.
///
/// The two payloads are single string literals on purpose: a long chain of `+`-joined string
/// fragments is exactly the shape that makes the Swift type-checker crawl, while one literal
/// per image costs it nothing.
enum AorusAIBrandLogo {
    /// The mark that reads on the page it is drawn over: the glowing white "A" on a dark page,
    /// the inked violet "A" on a light one. Decoded once and kept.
    static func image(dark: Bool) -> UIImage? {
        if dark {
            if cachedDark == nil { cachedDark = decode(darkBase64) }
            return cachedDark
        } else {
            if cachedLight == nil { cachedLight = decode(lightBase64) }
            return cachedLight
        }
    }

    private static var cachedDark: UIImage?
    private static var cachedLight: UIImage?

    private static func decode(_ base64: String) -> UIImage? {
        guard let data = Data(base64Encoded: base64), let image = UIImage(data: data) else { return nil }
        return image
    }

    private static let darkBase64 = ""

    private static let lightBase64 = ""
}
